mapper.select:
SELECT COALESCE(SUM(t.initial_quantity), 0) AS initial_quantity, COALESCE(SUM(t.available_quantity), 0) AS available_quantity, COALESCE(SUM(t.locked_quantity), 0) AS locked_quantity, COALESCE(SUM(t.sold_quantity), 0) AS sold_quantity, COALESCE(SUM(t.stock_amount), 0) AS stock_amount FROM ( SELECT p.id, COALESCE(SUM(b.initial_quantity), 0) AS initial_quantity, COALESCE(SUM(b.available_quantity), 0) AS available_quantity, COALESCE(SUM(b.locked_quantity), 0) AS locked_quantity, COALESCE(SUM(b.sold_quantity), 0) AS sold_quantity, COALESCE(SUM(b.available_quantity * b.unit_cost), 0) AS stock_amount, p.warning_stock FROM biz_product p LEFT JOIN biz_inventory_batch b ON b.product_id = p.id AND b.deleted = 0 WHERE p.deleted = 0
AND (p.product_code LIKE CONCAT('%', #{keyword}, '%') OR p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.brand LIKE CONCAT('%', #{keyword}, '%') OR p.model LIKE CONCAT('%', #{keyword}, '%'))
AND p.product_type_id IN
#{typeId}
AND p.product_type_id = #{productTypeId}
GROUP BY p.id, p.warning_stock
HAVING COALESCE(SUM(b.available_quantity), 0) <= p.warning_stock
) t
